import { DspMotion, DspReveal } from "../components/common/DspMotion";
import GainDemo from "../components/common/GainDemo";
import DspConceptDemo from "../components/common/DspConceptDemo";
import PageSeo from "../components/common/PageSeo";
import Footer from "../components/layout/Footer";
import { pageMetadata } from "../config/site";
import { dspStructuredData } from "../config/prerender";
import {
  dspDictionaryOverview,
  dspDictionaryReferenceIntro,
  dspDictionarySections,
  dspDictionaryTopicGroups,
} from "../data/dspDictionary";

const renderParagraphs = (paragraphs, keyPrefix) => (
  <div className="dictionary-prose">
    {paragraphs.map((paragraph, index) => (
      <p key={`${keyPrefix}-${index}`}>{paragraph}</p>
    ))}
  </div>
);

function DspDictionary() {
  return (
    <DspMotion>
      <PageSeo
        {...pageMetadata.dspDictionary}
        structuredData={dspStructuredData}
      />
      <main id="dsp-dictionary-page">
        <DspReveal as="section" className="dictionary-hero">
          <div className="dictionary-shell">
            <p className="dictionary-eyebrow">DSP, plugins, and systems design</p>
            <h1>{dspDictionaryOverview.title}</h1>
            <p className="dictionary-subtitle">{dspDictionaryOverview.subtitle}</p>
            <p className="dictionary-intro">{dspDictionaryOverview.intro}</p>
          </div>
        </DspReveal>

        <DspReveal as="section" className="dictionary-navigation">
          <div className="dictionary-shell">
            <div className="dictionary-card-grid">
              {dspDictionarySections.map((section) => (
                <a key={section.id} className="dictionary-card" href={`#${section.id}`}>
                  <span className="dictionary-card-label">{section.title}</span>
                  <span className="dictionary-card-copy">{section.summary}</span>
                </a>
              ))}
              <a className="dictionary-card" href="#dictionary-topics">
                <span className="dictionary-card-label">Concept Index</span>
                <span className="dictionary-card-copy">
                  Jump across DSP topics: filtering, dynamics, modulation, distortion,
                  spatial processing, and mix fundamentals.
                </span>
              </a>
            </div>
          </div>
        </DspReveal>

        <section className="dictionary-content">
          <div className="dictionary-shell dictionary-layout">
            <aside className="dictionary-sidebar">
              <div className="dictionary-sidebar-panel">
                <h2 id="dictionary-topics">Concept Index</h2>
                {dspDictionaryTopicGroups.map((group) => (
                  <div key={group.title} className="dictionary-topic-group">
                    <h3>{group.title}</h3>
                    <ul>
                      {group.topics.map((topic) => (
                        <li key={topic.id}>
                          <a href={`#${topic.id}`}>{topic.title}</a>
                        </li>
                      ))}
                    </ul>
                  </div>
                ))}
              </div>
            </aside>

            <div className="dictionary-main">
              {dspDictionarySections.map((section) => (
                <article key={section.id} id={section.id} className="dictionary-section">
                  <DspReveal as="header" className="dictionary-section-header">
                    <p className="dictionary-section-kicker">Foundations</p>
                    <h2>{section.title}</h2>
                  </DspReveal>
                  {renderParagraphs(section.paragraphs, section.id)}
                  <DspConceptDemo topicId={section.id} headingLevel={3} />
                </article>
              ))}

              <article id="dsp-dictionary" className="dictionary-section">
                <DspReveal as="header" className="dictionary-section-header">
                  <p className="dictionary-section-kicker">Reference</p>
                  <h2>An Audio DSP Very Informal Dictionary</h2>
                </DspReveal>
                {renderParagraphs(dspDictionaryReferenceIntro, "reference-intro")}

                {dspDictionaryTopicGroups.map((group) => (
                  <section key={group.title} className="dictionary-topic-cluster">
                    <h3>{group.title}</h3>
                    {group.topics.map((topic) => (
                      <section key={topic.id} id={topic.id} className="dictionary-topic">
                        <DspReveal as="h4">{topic.title}</DspReveal>
                        {renderParagraphs(topic.body, topic.id)}
                        {topic.id === "gain" ? <GainDemo headingLevel={5} /> : <DspConceptDemo topicId={topic.id} />}
                        {topic.code ? (
                          <pre className="dictionary-code"><code>{topic.code}</code></pre>
                        ) : null}
                      </section>
                    ))}
                  </section>
                ))}
              </article>
            </div>
          </div>
        </section>
      </main>
      <Footer />
    </DspMotion>
  );
}

export default DspDictionary;

