files.src/components/layout/Footer.js:
import { Link } from "react-router-dom";
import {
  legalLinks,
} from "../../config/site";
import useSiteNavigation from "../../hooks/useSiteNavigation";
import useSectionSite from "../../hooks/useSectionSite";
import SocialLinks from "../common/SocialLinks";

function Footer() {
  const { getItemHref, handleNavigationClick } = useSiteNavigation();
  const { footerQuickLinks, siteSwitchLinks, site } = useSectionSite();

  const renderFooterLink = (link) => {
    if (link.type === "external") {
      return (
        <a
          key={link.label}
          href={getItemHref(link)}
          target={link.target}
          rel={link.rel}
        >
          {link.label}
        </a>
      );
    }

    return (
      <Link
        key={link.label}
        to={getItemHref(link)}
        onClick={(event) => handleNavigationClick(event, link)}
      >
        {link.label}
      </Link>
    );
  };

  return (
    <footer className="footer">
      <div className="footer-content">
        <div className="social-media">
          <h4>Follow Me</h4>
          <SocialLinks />
        </div>

        <div className="quick-links">
          <h4>{site.title}</h4>
          {footerQuickLinks.map((link) => renderFooterLink(link))}
        </div>

        {site.key !== "gateway" ? (
          <div className="quick-links">
            <h4>Other Sites</h4>
            {siteSwitchLinks.map((link) => renderFooterLink(link))}
          </div>
        ) : null}

        <div className="legal">
          {legalLinks.map((link) => renderFooterLink(link))}
          <p>&copy; {new Date().getFullYear()} Jaime Osvaldo</p>
        </div>
      </div>
    </footer>
  );
}

export default Footer;

