import { siteMetadata } from "./site";

export const sectionSites = {
  gateway: {
    key: "gateway",
    label: "All Sites",
    title: "Jaime Osvaldo",
    basePath: "/",
    subdomain: siteMetadata.url,
  },
  film: {
    key: "film",
    label: "Film",
    title: "Film Sound",
    basePath: "/film",
    subdomain: "https://film.jaimeosvaldo.com",
  },
  live: {
    key: "live",
    label: "Live",
    title: "Live / Theatre",
    basePath: "/live",
    subdomain: "https://live.jaimeosvaldo.com",
  },
  dev: {
    key: "dev",
    label: "Dev",
    title: "Software & DSP",
    basePath: "/dev",
    subdomain: "https://dev.jaimeosvaldo.com",
  },
  art: {
    key: "art",
    label: "Art",
    title: "Animation & Art",
    basePath: "/art",
    subdomain: "https://art.jaimeosvaldo.com",
  },
};

const hostedSitePrefixes = ["film", "live", "dev", "art"];

function normalizeHostname(hostname = "") {
  return hostname.toLowerCase().replace(/:\d+$/, "");
}

function normalizeLocalPath(localPath = "/") {
  if (!localPath || localPath === "/") {
    return "/";
  }

  const prefixedPath = localPath.startsWith("/") ? localPath : `/${localPath}`;
  return prefixedPath.replace(/\/+$/, "");
}

export function getHostedSiteKey(hostname = "") {
  const normalizedHostname = normalizeHostname(hostname);

  if (!normalizedHostname) {
    return null;
  }

  return (
    hostedSitePrefixes.find((prefix) =>
      normalizedHostname.startsWith(`${prefix}.jaimeosvaldo.com`)
    ) || null
  );
}

export function getPathSiteKey(pathname = "/") {
  if (pathname.startsWith("/film")) {
    return "film";
  }

  if (pathname.startsWith("/live")) {
    return "live";
  }

  if (pathname.startsWith("/dev")) {
    return "dev";
  }

  if (pathname.startsWith("/art")) {
    return "art";
  }

  return "gateway";
}

export function getCurrentSiteKey(pathname = "/", hostname = "") {
  return getHostedSiteKey(hostname) || getPathSiteKey(pathname);
}

export function getCurrentSite(pathname = "/", hostname = "") {
  return sectionSites[getCurrentSiteKey(pathname, hostname)] || sectionSites.gateway;
}

export function getSiteRoute(
  siteKey,
  localPath = "/",
  hostname = getBrowserHostname()
) {
  const normalizedLocalPath = normalizeLocalPath(localPath);
  const hostedSiteKey = getHostedSiteKey(hostname);

  if (siteKey === "gateway") {
    return normalizedLocalPath;
  }

  if (hostedSiteKey === siteKey) {
    return normalizedLocalPath;
  }

  const site = sectionSites[siteKey];

  if (!site) {
    return normalizedLocalPath;
  }

  return normalizedLocalPath === "/"
    ? site.basePath
    : `${site.basePath}${normalizedLocalPath}`;
}

function createRouteItem({ label, siteKey, localPath = "/", icon }) {
  return {
    label,
    type: "route",
    to: getSiteRoute(siteKey, localPath, getBrowserHostname()),
    icon,
  };
}

function createSectionItem({ label, siteKey, sectionId, icon }) {
  return {
    label,
    type: "section",
    to: getSiteRoute(siteKey, "/", getBrowserHostname()),
    sectionId,
    icon,
  };
}

function createResumeItem() {
  return {
    label: "Resume",
    type: "external",
    href: siteMetadata.resumePath,
    icon: "resume",
    target: "_blank",
    rel: "noopener noreferrer",
  };
}

function createGatewayItem(currentSiteKey) {
  const hostedSiteKey = getHostedSiteKey(getBrowserHostname());

  if (hostedSiteKey) {
    return {
      label: "All Sites",
      type: "external",
      href: sectionSites.gateway.subdomain,
      icon: "home",
      target: "_self",
      rel: undefined,
    };
  }

  return {
    label: currentSiteKey === "gateway" ? "All Sites" : "All Sites",
    type: "route",
    to: "/",
    icon: "home",
  };
}

function getBrowserHostname() {
  return typeof window !== "undefined" ? window.location.hostname : "";
}

export function getNavigationForSite(siteKey) {
  switch (siteKey) {
    case "film":
      return [
        createRouteItem({ label: "Film", siteKey: "film", icon: "home" }),
        createRouteItem({
          label: "Samples",
          siteKey: "film",
          localPath: "/samples",
          icon: "portfolio",
        }),
        createGatewayItem("film"),
        createResumeItem(),
        createSectionItem({
          label: "Contact",
          siteKey: "film",
          sectionId: "contact",
          icon: "contact",
        }),
      ];
    case "live":
      return [
        createRouteItem({ label: "Live", siteKey: "live", icon: "home" }),
        createRouteItem({
          label: "Companies",
          siteKey: "live",
          localPath: "/companies",
          icon: "work",
        }),
        createGatewayItem("live"),
        createResumeItem(),
        createSectionItem({
          label: "Contact",
          siteKey: "live",
          sectionId: "contact",
          icon: "contact",
        }),
      ];
    case "dev":
      return [
        createRouteItem({ label: "Dev", siteKey: "dev", icon: "home" }),
        createRouteItem({
          label: "Projects",
          siteKey: "dev",
          localPath: "/projects",
          icon: "software",
        }),
        createRouteItem({
          label: "DSP Dictionary",
          siteKey: "dev",
          localPath: "/dsp-dictionary",
          icon: "work",
        }),
        createGatewayItem("dev"),
        createSectionItem({
          label: "Contact",
          siteKey: "dev",
          sectionId: "contact",
          icon: "contact",
        }),
      ];
    case "art":
      return [
        createRouteItem({ label: "Art", siteKey: "art", icon: "home" }),
        createGatewayItem("art"),
        { label: "Contact", type: "external", href: `mailto:${siteMetadata.email}`, icon: "contact", target: "_self" },
      ];
    default:
      return [
        createRouteItem({ label: "Film", siteKey: "film", icon: "portfolio" }),
        createRouteItem({ label: "Live", siteKey: "live", icon: "work" }),
        createRouteItem({ label: "Dev", siteKey: "dev", icon: "software" }),
        createRouteItem({ label: "Art", siteKey: "art", icon: "home" }),
        createResumeItem(),
      ];
  }
}

export function getFooterQuickLinks(siteKey) {
  switch (siteKey) {
    case "film":
      return [
        createRouteItem({ label: "Film Home", siteKey: "film", icon: "home" }),
        createRouteItem({
          label: "Samples",
          siteKey: "film",
          localPath: "/samples",
          icon: "portfolio",
        }),
        createSectionItem({
          label: "Contact",
          siteKey: "film",
          sectionId: "contact",
          icon: "contact",
        }),
      ];
    case "live":
      return [
        createRouteItem({ label: "Live Home", siteKey: "live", icon: "home" }),
        createRouteItem({
          label: "Companies",
          siteKey: "live",
          localPath: "/companies",
          icon: "work",
        }),
        createSectionItem({
          label: "Contact",
          siteKey: "live",
          sectionId: "contact",
          icon: "contact",
        }),
      ];
    case "dev":
      return [
        createRouteItem({ label: "Dev Home", siteKey: "dev", icon: "home" }),
        createRouteItem({
          label: "Projects",
          siteKey: "dev",
          localPath: "/projects",
          icon: "software",
        }),
        createRouteItem({
          label: "DSP Dictionary",
          siteKey: "dev",
          localPath: "/dsp-dictionary",
          icon: "work",
        }),
      ];
    case "art":
      return [
        createRouteItem({ label: "Art Home", siteKey: "art", icon: "home" }),
        { label: "Contact", type: "external", href: `mailto:${siteMetadata.email}`, icon: "contact", target: "_self" },
      ];
    default:
      return [
        createRouteItem({ label: "Film", siteKey: "film", icon: "portfolio" }),
        createRouteItem({ label: "Live", siteKey: "live", icon: "work" }),
        createRouteItem({ label: "Dev", siteKey: "dev", icon: "software" }),
        createRouteItem({ label: "Art", siteKey: "art", icon: "home" }),
      ];
  }
}

function createSiteSwitchItem(siteKey, currentSiteKey) {
  const hostedSiteKey = getHostedSiteKey(getBrowserHostname());

  if (hostedSiteKey && hostedSiteKey !== siteKey) {
    return {
      label: sectionSites[siteKey].title,
      type: "external",
      href: sectionSites[siteKey].subdomain,
      icon: siteKey === "dev" ? "software" : "work",
      target: "_self",
    };
  }

  return createRouteItem({
    label: sectionSites[siteKey].title,
    siteKey,
    icon: siteKey === "dev" ? "software" : "work",
  });
}

export function getSiteSwitchLinks(currentSiteKey) {
  return ["film", "live", "dev", "art"]
    .filter((siteKey) => siteKey !== currentSiteKey)
    .map((siteKey) => createSiteSwitchItem(siteKey, currentSiteKey));
}

